Hi,
I would like to improve torch.utils.data.TensorDataset by adding the possibility of custom transforms (just like torchvision.ImageFolder) and the possibility of not having a target tensor.
I have implemented the following changes:
class TensorsDataset(torch.utils.data.Dataset):

    '''
    A simple loading dataset - loads the tensor that are passed in input. This is the same as
    torch.utils.data.TensorDataset except that you can add transformations to your data and target tensor.
    Target tensor can also be None, in which case it is not returned.
    '''

    def __init__(self, data_tensor, target_tensor=None, transforms=None, target_transforms=None):
        if target_tensor is not None:
            assert data_tensor.size(0) == target_tensor.size(0)
        self.data_tensor = data_tensor
        self.target_tensor = target_tensor

        if transforms is None:
            transforms = []
        if target_transforms is None:
            target_transforms = []

        if not isinstance(transforms, list):
            transforms = [transforms]
        if not isinstance(target_transforms, list):
            target_transforms = [target_transforms]

        self.transforms = transforms
        self.target_transforms = target_transforms

    def __getitem__(self, index):

        data_tensor = self.data_tensor[index]
        for transform in self.transforms:
            data_tensor = transform(data_tensor)

        if self.target_tensor is None:
            return data_tensor

        target_tensor = self.target_tensor[index]
        for transform in self.target_transforms:
            target_tensor = transform(target_tensor)

        return data_tensor, target_tensor

    def __len__(self):
        return self.data_tensor.size(0)

I was trying to implement a custom neural network module when I encountered this bug. Only parameters which are defined as attributes of module directly are listed in module.parameters().
Code to reproduce bug:
class Module1(nn.Module):
    def __init__(self, input_size, hidden_size):
        super(Module1, self).__init__()

        self.w_i = nn.Parameter(torch.FloatTensor(input_size, hidden_size))


class Module2(nn.Module):
    def __init__(self, input_size, hidden_size):
        super(Module2, self).__init__()

        self.weights = {}
        self.weights['w_i'] = nn.Parameter(torch.FloatTensor(input_size, hidden_size))

m = Module1(512, 512)
print('m parameters:')

for i in m.parameters():
     print(i)

m2 = Module2(512, 512)
print('m2 parameters:')

for i in m2.parameters():
    print(i)

Pytorch version: 0.3.0
It makes sense to have parameters which are nested within lists or dictionaries, so shouldn't module.parameters() list all parameters defined within a module?
